t,storage_path,original_name,mime_type,file_size,created_by)VALUES(:vehicle,:type,:number,:issued,:expires,:path,:original,:mime,:size,:user)',['vehicle'=>$vehicle['id'],'type'=>validateChoice($_POST['document_type']??'',['registration','insurance','technical_inspection','tax','other'],'other'),'number'=>trim((string)($_POST['document_number']??'')),'issued'=>($_POST['issued_at']??'')?:null,'expires'=>($_POST['expires_at']??'')?:null,'path'=>$stored['path'],'original'=>$stored['original_name'],'mime'=>$stored['mime_type'],'size'=>$stored['size'],'user'=>currentUserId()]);auditLog('vehicle_document.created','vehicle_document',db()->lastInsertId(),null,['vehicle_id'=>$vehicle['id'],'type'=>$_POST['document_type']],$vehicle['agency_id']);flash('success',t('message.vehicle_document_stored'));}}catch(InvalidArgumentException|DomainException $exception){flash('danger',$exception->getMessage());}catch(Throwable $exception){reportDatabaseError($exception,'Maintenance operation failed');flash('danger',t('message.maintenance_failed'));}safeRedirect('maintenance.php');}
